INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_BAS_UNBEGOTTEN_IREN','ENT_BAS_UNBEGOTTEN','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','AH I.24','Christ then instructed them as to the nature of their conjunction, and taught them that those who possessed a comprehension of the Unbegotten were sufficient for themselves. He also announced among them what related to the knowledge of the Father,-namely, that he cannot be understood or comprehended, nor so much as seen or heard, except in so far as he is known by Monogenes only.','Roberts & Rambaut (Ante-Nicene Fathers, Vol. I)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS/Against_Heresies:_Book_I',NULL,'heresiological-verbatim','HOSTILE WITNESS: Irenaeus reports the Valentinian system in order to refute it; not a self-description.',true,'Located by name within Against Heresies; confirm the exact chapter.section locus cited.',DATE '2026-06-18','name-anchored within the work + substring gate (Ante-Nicene Fathers text); section locus per attestation',1),
('CIT_SAT_SEVEN_ANGELS_IREN','ENT_SAT_SEVEN_ANGELS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','AH I.24.1-2','What work, then, will they point to as having been accomplished through themselves by the Saviour, or by their Mother, either greater, or more glorious, or more adorned with wisdom, than those which have been produced by Him who was the disposer of all around us? What heavens have they established? what earth have they founded? what stars have they called into existence? or what lights of heaven have they caused to shine? with','Roberts & Rambaut (Ante-Nicene Fathers, Vol. I)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS/Against_Heresies:_Book_I',NULL,'heresiological-verbatim','HOSTILE WITNESS: Irenaeus reports the Valentinian system in order to refute it; not a self-description.',true,'Located by name within Against Heresies; confirm the exact chapter.section locus cited.',DATE '2026-06-18','name-anchored within the work + substring gate (Ante-Nicene Fathers text); section locus per attestation',1),
('CIT_SIM_GREAT_POWER_IREN','ENT_SIM_GREAT_POWER','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','AH I.23','These hold that the knowledge of the unspeakable Greatness is itself perfect redemption. For since both defect and passion flowed from ignorance, the whole substance of what was thus formed is destroyed by knowledge; and therefore knowledge is the redemption of the inner man.','Roberts & Rambaut (Ante-Nicene Fathers, Vol. I)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS/Against_Heresies:_Book_I',NULL,'heresiological-verbatim','HOSTILE WITNESS: Irenaeus reports the Valentinian system in order to refute it; not a self-description.',true,'Located by name within Against Heresies; confirm the exact chapter.section locus cited.',DATE '2026-06-18','name-anchored within the work + substring gate (Ante-Nicene Fathers text); section locus per attestation',1),
('CIT_SIM_HELENA_IREN','ENT_SIM_HELENA','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','AH I.23.2','Now this Simon of Samaria, from whom all sorts of heresies derive their origin, formed his sect out of the following materials:-Having redeemed from slavery at Tyre, a city of Phoenicia, a certain woman named Helena, he was in the habit of carrying her about with him, declaring that this woman was the first conception of his mind, the mother of all, by whom, in the beginning, he conceived in his mind of forming angels and arch','Roberts & Rambaut (Ante-Nicene Fathers, Vol. I)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS/Against_Heresies:_Book_I',NULL,'heresiological-verbatim','HOSTILE WITNESS: Irenaeus reports the Valentinian system in order to refute it; not a self-description.',true,'Located by name within Against Heresies; confirm the exact chapter.section locus cited.',DATE '2026-06-18','name-anchored within the work + substring gate (Ante-Nicene Fathers text); section locus per attestation',1),
('CIT_SIM_SIMON_IREN','ENT_SIM_SIMON','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','AH I.23','At present, however, I have simply been led to mention him, that thou mightest know that all those who in any way corrupt the truth, and injuriously affect the preaching of the Church, are the disciples and successors of Simon Magus of Samaria. Although they do not confess the name of their master, in order all the more to seduce others, yet they do teach his doctrines.','Roberts & Rambaut (Ante-Nicene Fathers, Vol. I)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS/Against_Heresies:_Book_I',NULL,'heresiological-verbatim','HOSTILE WITNESS: Irenaeus reports the Valentinian system in order to refute it; not a self-description.',true,'Located by name within Against Heresies; confirm the exact chapter.section locus cited.',DATE '2026-06-18','name-anchored within the work + substring gate (Ante-Nicene Fathers text); section locus per attestation',1),
('CIT_VAL_AGAPE_IREN','ENT_VAL_AGAPE','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','AH I.2.5','They then add that Anthropos himself, along with Ecclesia, produced twelve Aeons, to whom they give the following names: Paracletus and Pistis, Patricos and Elpis, Metricos and Agape, Ainos and Synesis, Ecclesiasticus and Macariotes, Theletos and Sophia. 3. Such are the thirty Aeons in the erroneous system of these men; and they are described as being wrapped up, so to speak, in silence, and known to none .','Roberts & Rambaut (Ante-Nicene Fathers, Vol. I)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS/Against_Heresies:_Book_I',NULL,'heresiological-verbatim','HOSTILE WITNESS: Irenaeus reports the Valentinian system in order to refute it; not a self-description.',true,'Located by name within Against Heresies; confirm the exact chapter.section locus cited.',DATE '2026-06-18','name-anchored within the work + substring gate (Ante-Nicene Fathers text); section locus per attestation',1),
('CIT_VAL_AGERATOS_IREN','ENT_VAL_AGERATOS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Against Heresies (Book I)','Logos and Zoe, after producing Anthropos and Ecclesia, sent forth other ten Aeons, whose names are the following: Bythius and Mixis, Ageratos and Henosis, Autophyes and Hedone, Acinetos and Syncrasis, Monogenes and Macaria. These are the ten Aeons whom they declare to have been produced by Logos and Zoe.','Roberts & Rambaut (Ante-Nicene Fathers, Vol. I)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS/Against_Heresies:_Book_I',NULL,'heresiological-verbatim','HOSTILE WITNESS: Irenaeus reports the Valentinian system in order to refute it; not a self-description.',true,'Located by name within Against Heresies; confirm the exact chapter.section locus cited.',DATE '2026-06-18','name-anchored within the work + substring gate (Ante-Nicene Fathers text); section locus per attestation',1),
